function currentSiteContext(){const ctx={boundary:siteClosed?{vertices:siteVertices,evidence:{status:$('site-boundary-status').value,source:$('site-boundary-source').value,reference:$('site-reference').value.trim()}}:undefined,notes:$('site-notes').value.trim()};if($('site-north').value!=='')ctx.orientation={northBearingDeg:Number($('site-north').value),evidence:{status:'provided',source:'owner_input'}};if($('site-slope').value!==''){ctx.slope={percent:Number($('site-slope').value),evidence:{status:'provided',source:'owner_input'}};const d=$('site-slope-direction').value.trim();if(d){const p=d.split(',').map(Number);if(p.length!==2||!p.every(Number.isFinite))throw Error('Slope direction must be x,y local coordinates.');ctx.slope.direction={x:p[0],y:p[1]};}}if($('site-access').value!=='unknown')ctx.access=[{type:$('site-access').value,label:'User-recorded access',evidence:{status:'provided',source:'owner_input'}}];const allowed=['setback','easement','watercourse','protected_tree','utility','right_of_way','hazard','other'];const constraints=$('site-constraints').value.split('\n').map(x=>x.trim()).filter(Boolean).map((line,i)=>{const p=line.split('|').map(x=>x.trim());if(!allowed.includes(p[0]))throw Error('Unsupported constraint type on line '+(i+1)+'.');const d=p[2]===''||p[2]===undefined?null:Number(p[2]);if(d!==null&&!Number.isFinite(d))throw Error('Invalid constraint distance on line '+(i+1)+'.');return {type:p[0],side:p[1]||'unknown',...(d===null?{}:{distanceM:d}),label:p.slice(3).join(' | ')||p[0],evidence:{status:'provided',source:'owner_input'}};});if(constraints.length)ctx.constraints=constraints;if(siteZoneJsonError)throw Error('Correct the exclusion-zone JSON before saving or analysing the site.');if(siteVertices.length&&!siteClosed)throw Error('Finish or clear the parcel boundary before saving or analysing.');if(siteZoneVertices.length)throw Error('Finish or clear the current exclusion-zone polygon before saving or analysing.');if(siteExclusionZones.length)ctx.exclusionZones=siteExclusionZones;return ctx;}
function siteReport(data){$('site-report').innerHTML='<p class="eyebrow">PRELIMINARY SITE EVIDENCE REPORT</p><h3>Recorded parcel area: '+(data.summary.boundaryAreaM2===null?'Not available':data.summary.boundaryAreaM2.toFixed(2)+' m²')+'</h3><p class="warn">Decision: '+esc(data.decision)+' · Buildable envelope: NOT CALCULATED · Regulatory compliance: NOT VERIFIED</p><div class="check-grid">'+(data.findings||[]).map(x=>'<div><strong class="status-'+(x.severity==='blocking'?'failed':'warnings')+'">'+esc(x.severity.toUpperCase())+'</strong><span>'+esc(x.code.replaceAll('_',' '))+'</span><span>'+esc(x.message)+'</span></div>').join('')+'</div><p class="concept-note">'+esc(data.disclaimer)+'</p>';}
function invalidateSiteFit(disable=false){if(siteFitRevision){siteFitRevision=null;siteFitCandidates=[];siteDraw();$('site-fit-report').textContent='Site or building inputs changed. The previous footprint assessment is no longer current; run it again.';}if(disable)siteFitButton.disabled=true;}function invalidateSiteAnalysis(){invalidateSiteFit();if(!siteAnalysis&&!$('site-report').textContent.includes('PRELIMINARY SITE EVIDENCE REPORT'))return;siteAnalysis=null;$('site-report').textContent='Site details changed. The previous analysis is no longer current. Run the site analysis again before relying on this report.';}
for(const id of ['site-boundary-status','site-boundary-source','site-reference','site-north','site-slope','site-slope-direction','site-access','site-notes','site-constraints','site-exclusion-zones']){const field=$(id);field.addEventListener('input',invalidateSiteAnalysis);field.addEventListener('change',invalidateSiteAnalysis);}
